// TODO(Етап 1): назви полів підставити з виводу baf_00_discovery_odata.
// Зараз тут канонічна модель, до якої зводимо дані 1С перед відправкою в B24.
const cfg = $('Config').first().json;

const products = $('OData: номенклатура').all().flatMap((i) => i.json.value || [i.json]);
const stockRows = $('OData: залишки').all().flatMap((i) => i.json.value || [i.json]);

// Залишки: групуємо по номенклатурі та складу.
// TODO: узгодити формулу — фізичний залишок мінус резерв, чи з урахуванням "у виробництві".
const stockByRef = {};
for (const r of stockRows) {
  const ref = r.Номенклатура_Key || r.Nomenklatura_Key;
  if (!ref) continue;
  const store = r.Склад_Key || r.Sklad_Key || 'default';
  const qty = Number(r.КількістьBalance ?? r.QuantityBalance ?? r.КоличествоBalance ?? 0);
  stockByRef[ref] = stockByRef[ref] || { total: 0, byStore: {} };
  stockByRef[ref].total += qty;
  stockByRef[ref].byStore[store] = (stockByRef[ref].byStore[store] || 0) + qty;
}

const out = products.map((p) => {
  const ref = p.Ref_Key;
  const stock = stockByRef[ref] || { total: 0, byStore: {} };
  return {
    json: {
      xmlId: ref,
      sku: p.Артикул || p.Code || p.Код || '',
      name: (p.Description || p.Наименование || p.Найменування || '').trim(),
      unit: p.ОдиницяВиміру_Key || p.ЕдиницаИзмерения_Key || null,
      vat: p.СтавкаПДВ || p.СтавкаНДС || null,
      barcode: p.Штрихкод || null,
      groupRef: p.Parent_Key || null,
      isFolder: Boolean(p.IsFolder),
      quantity: stock.total,
      quantityByStore: stock.byStore
    }
  };
});

// Групи номенклатури не є товарами.
return out.filter((i) => !i.json.isFolder);

// Дельта: у Бітрікс24 їдуть лише позиції, що змінилися з попереднього прогону.
// MVP тримає стан у staticData воркфлоу (пишеться тільки у продакшн-виконаннях,
// не в ручному тесті). Етап 4 переносить це в таблицю Postgres.
const crypto = require('crypto');
const store = $getWorkflowStaticData('global');
store.hashes = store.hashes || {};

const changed = [];
let unchanged = 0;

for (const item of $input.all()) {
  const d = item.json;
  const significant = JSON.stringify([d.sku, d.name, d.unit, d.vat, d.barcode, d.quantity, d.quantityByStore]);
  const hash = crypto.createHash('sha1').update(significant).digest('hex');
  if (store.hashes[d.xmlId] === hash) {
    unchanged++;
    continue;
  }
  changed.push({ json: { ...d, _hash: hash } });
}

if (changed.length === 0) {
  return [{ json: { _empty: true, unchanged } }];
}
return changed;

// Збираємо пакети batch по 50 команд (ліміт Бітрікс24).
// TODO(Етап 2): метод і склад полів залежать від рішення по каталогу:
//   catalog.product.* + catalog.product.offer.*  — якщо є торговий каталог і торгові пропозиції
//   crm.product.*                                — якщо тільки товари CRM
// TODO(Етап 3): при увімкненому складському обліку кількість не ставиться напряму —
//   потрібні catalog.document.add / .element.add / .conduct замість поля QUANTITY.
const BATCH_LIMIT = 50;
const items = $input.all().filter((i) => !i.json._empty);
if (items.length === 0) return [{ json: { _empty: true } }];

function toQuery(obj, prefix) {
  const parts = [];
  for (const [k, v] of Object.entries(obj)) {
    if (v === null || v === undefined) continue;
    const key = prefix ? `${prefix}[${k}]` : k;
    if (typeof v === 'object' && !Array.isArray(v)) {
      parts.push(toQuery(v, key));
    } else {
      parts.push(`${encodeURIComponent(key)}=${encodeURIComponent(v)}`);
    }
  }
  return parts.filter(Boolean).join('&');
}

const commands = items.map((i) => {
  const d = i.json;
  const fields = {
    NAME: d.name,
    XML_ID: d.xmlId,
    PROPERTY_ARTICUL: d.sku,
    QUANTITY: d.quantity
  };
  // Оновлення за XML_ID робиться через пошук + update; на Етапі 2 замінюємо
  // на реальний ідентифікатор товару з попереднього прогону (мапа xmlId → b24Id).
  return `crm.product.add?${toQuery({ fields }, '')}`;
});

const packets = [];
for (let i = 0; i < commands.length; i += BATCH_LIMIT) {
  const slice = commands.slice(i, i + BATCH_LIMIT);
  const cmd = {};
  slice.forEach((c, idx) => { cmd[`c${idx}`] = c; });
  packets.push({ json: { halt: 0, cmd, _count: slice.length } });
}
return packets;

// Підсумок прогону + фіксація хешів. Хеші зберігаємо ТІЛЬКИ після успішної
// відправки, інакше після падіння дельта "проглотить" незалитi зміни.
const store = $getWorkflowStaticData('global');
store.hashes = store.hashes || {};

let sent = 0;
const errors = [];
for (const item of $input.all()) {
  const body = item.json || {};
  const result = body.result || {};
  const resultErrors = result.result_error || {};
  const errKeys = Object.keys(resultErrors);
  if (body.error || errKeys.length) {
    errors.push({ error: body.error || null, commandErrors: resultErrors });
  }
  sent += Object.keys(result.result || {}).length;
}

if (errors.length === 0) {
  for (const item of $('Дельта').all()) {
    const d = item.json;
    if (d._hash) store.hashes[d.xmlId] = d._hash;
  }
}

return [{
  json: {
    finishedAt: new Date().toISOString(),
    sent,
    errorPackets: errors.length,
    errors: errors.slice(0, 10),
    hashesStored: Object.keys(store.hashes).length
  }
}];
